/**
 * Live availability check for a customer-chosen free subdomain (`<label>.<base>`).
 * Advisory UX for the deploy wizard — the authoritative de-dup is the atomic
 * UNIQUE(hostname) claim inside orderHostingAccount's charge tx, so a check that
 * says "available" can still lose a race and fail the order cleanly (no charge).
 */
export async function checkHostingSubdomain(
  labelRaw: string,
): Promise<{ available: boolean; fqdn: string; reason?: string }> {
  await requireUser();
  const label = String(labelRaw ?? "").trim().toLowerCase();
  const fqdn = freeSubdomainFor(label);
  if (!label) return { available: false, fqdn, reason: "Enter a subdomain." };
  if (!isValidSubdomainLabel(label)) {
    return { available: false, fqdn, reason: "Use 1–32 letters, digits or hyphens (start/end with a letter or digit)." };
  }
  if (!isValidHostingDomain(fqdn)) {
    return { available: false, fqdn, reason: "That subdomain isn’t a valid hostname." };
  }
  if (await isHostnameClaimed(fqdn)) {
    return { available: false, fqdn, reason: "Already taken — try another." };
  }
  return { available: true, fqdn };
}

